rototype.hasOwnProperty,Sc=Object.prototype.propertyIsEnumerable,n5=(e,t,n)=>t in e?bc(e,t,{enumerable:!0,configurable:!0,writable:!0,value:n}):e[t]=n,jc=(e,t)=>{for(var n in t||(t={}))Ic.call(t,n)&&n5(e,n,t[n]);if(t5)for(var n of t5(t))Sc.call(t,n)&&n5(e,n,t[n]);return e},zc=(e,t)=>wc(e,vc(t));function Ci(e,t="key",n){const{title:u,array:i,colKey:a}=e;if(i.length===0)return;const s={};i.forEach(o=>{const{text:l,type:c}=o,g=o[t],h=s[g];h?h.type.push(c):s[g]=zc(jc({},o),{type:[c]})});const r={title:u,texts:s,colKey:a};return n&&(r.appendText=n),r}const N2={title:"五运太过、不及病候(《气交变大论》)",[K.JUE_YIN]:{TAIGUO:"<i>岁木太过，风气流行，脾土受邪。</i><b>民病飧泄食减，体重烦冤，肠鸣腹支满</b><i>，上应岁星。</i><b>甚则忽忽善怒，眩冒巓疾</b><i>。化气不政，生气独治。云物飞动，草木不宁，甚而摇落，</i><b>反胁痛而吐甚</b><i>，冲阳绝者死不治，上应太白星。</i>",BUJI:"<i>岁木不及，燥乃大行，生气失应，草木晚荣，肃杀而甚，则刚木辟著，柔萎苍干，上应太白星。</i><b>民病中清，胠胁痛，少腹痛，肠鸣溏泄</b><i>，凉雨时至，上应太白、岁星，其谷苍。上临阳明，生气失政，草木再荣，化气乃急，上应太白、镇星，其主苍早。复则炎暑流火，湿性燥，柔脆草木焦槁，下体再生，华实齐化，</i><b>病寒热疮疡、痱胗痈痤，</b><i>上应荧惑、太白，其谷白坚。白露早降，收杀气行，寒雨害物，虫食甘黄，脾土受邪，赤气后化，心气晚治，上胜肺金，白气乃屈，其谷不成，</i><b>咳而鼽</b><i>，上应荧惑、太白星。</i>"},[K.SHAO_YIN]:{TAIGUO:"<i>岁火太过，炎暑流行，肺金受邪。</i><b>民病疟，少气咳喘，血溢血泄注下，嗌燥耳聋，中热肩背热，</b><i>上应荧惑星。</i><b>甚则胸中痛，胁支满胁痛，膺背肩胛间痛，两臂内痛，身热肤痛而为浸淫。</b><i>收气不行，长气独明，雨冰霜寒，上应辰星。上临少阴少阳，火燔焫，水泉涸，物焦槁，病反</i><b>谵妄狂越，咳喘息鸣，下甚，血溢泄不已。</b><i>太渊绝者死不治，上应荧惑星。</i>",BUJI:"<i>岁火不及，寒乃大行，长政不用，物荣而下，凝惨而甚，则阳气不化，乃折荣美，上应辰星。</i><b>民病胸中痛，胁支满，两胁痛，膺背肩胛间及两臂内痛，郁冒朦昧，心痛暴喑，胸腹大，胁下与腰背相引而痛，甚则屈不能伸，髋髀如别，</b><i>上应荧惑、辰星，其谷丹。复则埃郁，大雨且至，黑气乃辱，病</i><b>鹜溏腹满，食饮不下，寒中肠鸣，泄注腹痛，暴挛痿痹，足不任身</b><i>，上应镇星、辰星，玄谷不成。</i>"},[K.TAI_YIN]:{TAIGUO:"<i>岁土太过，雨湿流行，肾水受邪，</i><b>民病腹痛，清厥意不乐，体重烦冤，</b><i>上应镇星。</i><b>甚则肌肉萎，足痿不收，行善瘈，脚下痛，饮发中满食减，四肢不举。</b><i>变生得位，藏气伏，化气独治之，泉涌河衍，涸泽生鱼，风雨大至，土崩溃，鳞见于陆，</i><b>病腹满溏泄肠鸣，反下甚</b><i>，而太溪绝则死不治，上应岁星。</i>",BUJI:"<i>岁土不及，风乃大行，化气不令，草木茂荣，飘扬而甚，秀而不实，上应岁星。</i><b>民病飧泄霍乱，体重腹痛，筋骨繇复，肌肉瞤酸，善怒</b><i>，藏气举事，蛰虫早附，咸病</i><b>寒中，</b><i>上应岁星、镇星，其谷䶖。复则收政严峻，名木苍雕，</i><b>胸胁暴痛，下引少腹，善太息，</b><i>虫食甘黄，气客于脾，䶖谷乃减，</i><b>民食少失味</b><i>，苍谷乃损，上应太白、岁星。上临厥阴，流水不冰，蛰虫来见，藏气不用，白乃不复，上应岁星，民乃康。</i>"},[K.YANG_MING]:{TAIGUO:"<i>岁金太过，燥气流行，肝木受邪，</i><b>民病两胁下少腹痛，目赤痛眦疡，耳无所闻</b><i>，肃杀而甚，则</i><b>体重烦冤，胸痛引背，两胁满且痛引少腹</b><i>，上应太白星。</i><b>甚则喘咳逆气，肩背痛，尻阴股膝髀腨䯒足皆病</b><i>，上应荧惑星。收气峻，生气下，草木敛，苍干雕陨，病反</i><b>暴痛，胠胁不可反侧，咳逆，甚而血溢</b><i>，太冲绝者死不治，上应太白星。</i>",BUJI:"<i>岁金不及，炎火乃行，生气乃用，长气专胜，庶物以茂，燥烁以行，上应荧惑星。</i><b>民病肩背瞀重，鼽嚏，血便注下</b><i>，收气乃后，上应太白、荧惑星，其谷坚芒。复则寒雨暴至，乃零冰雹霜雪杀物，阴厥且格，阳反上行，</i><b>头脑户痛，延及囟顶发热</b><i>，上应辰星、荧惑，丹谷不成，</i><b>民病口疮，甚则心痛。</b>"},[K.TAI_YANG]:{TAIGUO:"<i>岁水太过，寒气流行，邪害心火。</i><b>民病身热烦心躁悸，阴厥上下中寒，谵妄心痛，</b><i>寒气早至，上应辰星。</i><b>甚则腹大胫肿，喘咳，寝汗出憎风，</b><i>大雨至，埃雾朦郁，上应镇星。上临太阳，则雨冰雪霜不时降，湿气变物，病反</i><b>腹满肠鸣，溏泄食不化，渴而妄冒。</b><i>神门绝者死不治，上应荧惑、辰星。</i>",BUJI:"<i>岁水不及，湿乃大行，长气反用，其化乃速，暑雨数至，上应镇星。</i><b>民病腹满身重，濡泄，寒疡流水，腰股痛发，腘腨股膝不便，烦冤，足痿清厥，脚下痛，甚则跗肿，</b><i>藏气不政，肾气不衡，上应镇星、辰星，其谷秬。上临太阴，则大寒数举，蛰虫早藏，地积坚冰，阳光不治，民</i><b>病寒疾于下，甚则腹满浮肿，</b><i>上应镇星、荧惑，其主䶖谷。复则大风暴发，草偃木零，生长不鲜，</i><b>面色时变，筋骨并辟，肉瞤瘛，目视目巟目巟，物疏璺，肌肉胗发，气并膈中，痛于心腹</b><i>，黄气乃损，其谷不登，上应岁星。</i>"}},Y2={title:"四时不及病候(《气交变大论》)",[K.JUE_YIN]:{BUJI:"<i>木不及，春有鸣条律畅之化，则秋有雾露清凉之政；春有惨凄残贼之胜，则夏有炎暑燔烁之复。</i><b>其眚东，其脏肝，其病内舍胠胁，外在关节。</b>"},[K.SHAO_YIN]:{BUJI:"<i>火不及，夏有炳明光显之化，则冬有严肃霜寒之政；夏有惨凄凝冽之胜，则不时有埃昏大雨之复。</i><b>其眚南，其脏心，其病内舍膺胁，外在经络。</b>"},[K.TAI_YIN]:{BUJI:"<i>土不及，四维有埃云润泽之化，则春有鸣条鼓拆之政；四维发振拉飘腾之变，则秋有肃杀霖霪之复。</i><b>其眚四维，其脏脾，其病内舍心腹，外在肌肉四肢。</b>"},[K.YANG_MING]:{BUJI:"<i>金不及，夏有光显郁蒸之令，则冬有严凝整肃之应；夏有炎烁燔燎之变，则秋有冰雹霜雪之复。</i><b>其眚西，其脏肺，其病内舍膺胁肩背，外在皮毛。</b>"},[K.TAI_YANG]:{BUJI:"<i>水不及，四维有湍润埃云之化，则不时有和风生发之应；四维发埃昏骤注之变，则不时有飘荡振拉之复。</i><b>其眚北，其脏肾，其病内舍腰脊骨髓，外在溪谷踹膝。</b>"}},Tc="夫五运之政，犹权衡也，高者抑之，下者举之，化者应之，变者复之，此生长化收藏之理，气之常也，失常则天地四塞矣。故曰：天地之动静，神明为之纪，阴阳之往复，寒暑彰其兆。此之谓也。";function a2(e,t,n,u){var i,a;const{key:s,flagKey:r}=e;if(!s||!r||!u)return;const o=(i=N2==null?void 0:N2[s])==null?void 0:i[r],l=(a=Y2==null?void 0:Y2[s])==null?void 0:a[r];o&&t[0].array.push({key:`${s}__${r}`,text:o,type:n}),l&&t[1].array.push({key:`${s}__${r}`,text:l,type:n})}function Nc(e){const{birth:t,illness:n,current:u}=e,i=[{title:N2.title,array:[],colKey:"qijbdl_binghou"},{title:Y2.title,array:[],colKey:"qijbdl_sishi"}],a=mn(t);a2(a,i,"命",t.isShowDetail);const s=mn(n);a2(s,i,"病",n.isShowDetail);const r=mn(u);return a2(r,i,"时",u.isShowDetail),i.map(l=>Ci(l,"key",Tc)).filter(l=>{if(l!=null&&l.texts)return Object.keys(l.texts).length>0})}var Yc=Object.defineProperty,Mc=Object.defineProperties,kc=Object.getOwnPropertyDescriptors,u5=Object.getOwnPropertySymbols,Oc=Object.prototype.hasOwnProperty,Gc=Object.prototype.propertyIsEnumerable,i5=(e,t,n)=>t in e?Yc(e,t,{enumerable:!0,configurable:!0,writable:!0,value:n}):e[t]=n,pn=(e,t)=>{for(var n in t||(t={}))Oc.call(t,n)&&i5(e,n,t[n]);if(u5)for(var n of u5(t))Gc.call(t,n)&&i5(e,n,t[n]);return e},l1=(e,t)=>Mc(e,kc(t));const M0={TAI_YI_TIAN_FU:"TAI_YI_TIAN_FU",TIAN_FU:"TIAN_FU",TONG_TIAN_FU:"TONG_TIAN_FU",SUI_HUI:"SUI_HUI",TONG_SUI_HUI:"TONG_SUI_HUI",LEI_SUI_HUI:"LEI_SUI_HUI"},h0={JUE_YIN_410:"敷和",SHAO_YIN_115:"升明",TAI_YIN_126:"备化",YANG_MING_28:"审平",TAI_YANG_39:"静顺",JUE_YIN_410_B:"委和",SHAO_YIN_115_B:"伏明",TAI_YIN_126_B:"卑监",YANG_MING_28_B:"从革",TAI_YANG_39_B:"涸流",JUE_YIN_410_T:"发生",SHAO_YIN_115_T:"赫曦",TAI_YIN_126_T:"敦阜",YANG_MING_28_T:"坚成",TAI_YANG_39_T:"流衍"},xe=new Map;xe.set(h0.JUE_YIN_410,{name:h0.JUE_YIN_410,years:[{ganZhi:"丁巳",type:[M0.TAI_YI_TIAN_FU]},{ganZhi:"丁亥",type:[M0.TAI_YI_TIAN_FU]}]});xe.set(h0.SHAO_YIN_115,{name:h0.SHAO_YIN_115,years:[{ganZhi:"戊辰"},{ganZhi:"戊戌"},{ganZhi:"癸巳",type:[M0.LEI_SUI_HUI,M0.TONG_SUI_HUI]},{ganZhi:"癸亥"}]});xe.set(h0.TAI_YIN_126,{name:h0.TAI_YIN_126,years:[{ganZhi:"己丑",type:[M0.TAI_YI_TIAN_FU]},{ganZhi:"己未",type:[M0.TAI_YI_TIAN_FU]}]});xe.set(h0.YANG_MING_28,{name:h0.YANG_MING_28,years:[{ganZhi:"乙卯",type:[M0.TIAN_FU]},{ganZhi:"乙酉",type:[M0.TAI_YI_TIAN_FU]},{ganZhi:"庚子",type:[M0.TONG_TIAN_FU]},{ganZhi:"庚午",type:[M0.TONG_TIAN_FU]},{ganZhi:"庚寅"},{ganZhi:"庚申",type:[M0.LEI_SUI_HUI]}]});xe.set(h0.TAI_YANG_39,{name:h0.TAI_YANG_39,years:[{ganZhi:"辛亥",type:[M0.LEI_SUI_HUI]}]});xe.set(h0.JUE_YIN_410_B,{name:h0.JUE_YIN_410_B,years:[{ganZhi:"丁丑"},{ganZhi:"丁未"},{ganZhi:"丁卯",type:[M0.SUI_HUI]},{ganZhi:"丁酉"}]});xe.set(h0.SHAO_YIN_115_B,{name:h0.SHAO_YIN_115_B,years:[{ganZhi:"癸丑"},{ganZhi:"癸未"},{ganZhi:"癸卯",type:[M0.TONG_SUI_HUI]},{ganZhi:"癸酉",type:[M0.TONG_SUI_HUI]}]});xe.set(h0.TAI_YIN_126_B,{name:h0.TAI_YIN_126_B,years:[{ganZhi:"己卯"},{ganZhi:"己酉"},{ganZhi:"己巳"},{ganZhi:"己亥"}]});xe.set(h0.YANG_MING_28_B,{name:h0.YANG_MING_28_B,years:[{ganZhi:"乙丑"},{ganZhi:"乙未"},{ganZhi:"乙巳"},{ganZhi:"乙亥"}]});xe.set(h0.TAI_YANG_39_B,{name:h0.TAI_YANG_39_B,years:[{ganZhi:"辛丑",type:[M0.TONG_SUI_HUI]},{ganZhi:"辛未",type:[M0.TONG_SUI_HUI]},{ganZhi:"辛卯"},{ganZhi:"辛酉"}]});xe.set(h0.JUE_YIN_410_T,{name:h0.JUE_YIN_410_T,years:[{ganZhi:"壬子"},{ganZhi:"壬午"},{ganZhi:"壬寅",type:[M0.LEI_SUI_HUI,M0.TONG_TIAN_FU]},{ganZhi:"壬申",type:[M0.TONG_TIAN_FU]},{ganZhi:"壬辰"},{ganZhi:"壬戌"}]});xe.set(h0.SHAO_YIN_115_T,{name:h0.SHAO_YIN_115_T,years:[{ganZhi:"戊子",type:[M0.TIAN_FU]},{ganZhi:"戊午",type:[M0.TAI_YI_TIAN_FU]},{ganZhi:"戊寅",type:[M0.TIAN_FU]},{ganZhi:"戊申",type:[M0.TIAN_FU]}]});xe.set(h0.TAI_YIN_126_T,{name:h0.TAI_YIN_126_T,years:[{ganZhi:"甲子"},{ganZhi:"甲午"},{ganZhi:"甲寅"},{ganZhi:"甲申"},{ganZhi:"甲辰",type:[M0.SUI_HUI,M0.TONG_TIAN_FU]},{ganZhi:"甲戌",type:[M0.SUI_HUI,M0.TONG_TIAN_FU]}]});xe.set(h0.YANG_MING_28_T,{name:h0.YANG_MING_28_T,years:[{ganZhi:"庚辰"},{ganZhi:"庚戌"}]});xe.set(h0.TAI_YANG_39_T,{name:h0.TAI_YANG_39_T,years:[{ganZhi:"丙子",type:[M0.SUI_HUI]},{ganZhi:"丙午"},{ganZhi:"丙寅"},{ganZhi:"丙申"},{ganZhi:"丙辰",type:[M0.TIAN_FU]},{ganZhi:"丙戌",type:[M0.TIAN_FU]}]});const Wt={title:"三气之纪病候(《五常政大论》)",pingQi:{[h0.JUE_YIN_410]:"<i>敷和之纪，木德周行，阳舒阴布，五化宣平，其气端，其性随，其用曲直，其化生荣，其类草木，其政发散，其候温和，其令风，其脏肝，肝其畏清，其主目，其谷麻，其果李，其实核，其应春，其虫毛，其畜犬，其色苍，其养筋，</i><b>其病里急支满</b><i>，其味酸，其音角，其物中坚，</i><b>其数八</b>。",[h0.SHAO_YIN_115]:"<i>升明之纪，正阳而治，德施周普，五化均衡，其气高，其性速，其用燔灼，其化蕃茂，其类火，其政明曜，其候炎暑，其令热，其脏心，心其畏寒，其主舌，其谷麦，其果杏，其实络，其应夏，其虫羽，其畜马，其色赤，其养血，</i><b>其病瞤瘛，</b><i>其味苦，其音徵，其物脉，</i><b>其数七。</b>。",[h0.TAI_YIN_126]:"<i>备化之纪，气协天休，德流四政，五化齐修，其气平，其性顺，其用高下，其化丰满，其类土，其政安静，其候溽蒸，其令湿，其脏脾，脾其畏风，其主口，其谷稷，其果枣，其实肉，其应长夏，其虫倮，其畜牛，其色黄，其养肉，</i><b>其病否</b><i>，其味甘，其音宫，其物肤，</i><b>其数五</b>。",[h0.YANG_MING_28]:"<i>审平之纪，收而不争，杀而无犯，五化宣明，其气洁，其性刚，其用散落，其化坚敛，其类金，其政劲肃，其候清切，其令燥，其脏肺，肺其畏热，其主鼻，其谷稻，其果桃，其实壳，其应秋，其虫介，其畜鸡，其色白，其养皮毛，</i><b>其病咳，</b><i>其味辛，其音商，其物外坚，</i><b>其数九</b>。",[h0.TAI_YANG_39]:"<i>静顺之纪，藏而勿害，治而善下，五化成整，其气明，其性下，其用沃衍，其化凝坚，其类水，其政流演，其候凝肃，其令寒，其脏肾，肾其畏湿，其主二阴，其谷豆，其果栗，其实濡，其应冬，其虫鳞，其畜彘，其色黑，其养骨髓，</i><b>其病厥，</b><i>其味咸，其音羽，其物濡，</i><b>其数六</b>。",appendText:"故生而勿杀，长而勿罚，化而勿制，收而勿害，藏而勿抑，是谓平气。"},buJi:{[h0.JUE_YIN_410_B]:"<i>委和之纪，是谓胜生，生气不政，化气乃扬，长气自平，收令乃早，凉雨时降，风云并兴，草木晚荣，苍干雕落，物秀而实，肤肉内充，其气敛，其用聚，</i><b>其动緛戾拘缓，其发惊骇，其脏肝，</b><i>其果枣桃，其实核壳，其谷稷稻，其味酸辛，其色白苍，其畜犬鸡，其虫毛介，其主雾露凄沧，其声角商，</i><b>其病摇动注恐，</b><i>从金化也。少角与判商同，上角与正角同，上商与正商同。其甘虫，邪伤肝也。上宫与正宫同。萧飋肃杀则炎赫沸腾，眚于三，所谓复也。其主飞蠹蛆雉，乃为雷霆。</i><b>其病肢废，痈肿疮疡，</b><i>其甘虫，</i><b>邪伤肝也。</b><i>上宫与正宫同。萧飋肃杀则炎赫沸腾，</i><b>眚于三</b><i>，所谓复也。其主飞蠹蛆雉，乃为雷霆。</i>",[h0.SHAO_YIN_115_B]:"<i>伏明之纪，是谓胜长，长气不宣，藏气反布，收气自政，化令乃衡，寒清数举，暑令乃薄，承化物生，生而不长，成实而稚，遇化已老，阳气屈伏，蛰虫早藏，其气郁，其用暴，</i><b>其动疡伏变易，其发痛，其脏心，</b><i>其果栗桃，其实络濡。其谷豆稻，其味苦咸，其色玄丹，其畜马彘，其虫羽鳞，其主冰雪霜寒，其声徵羽，</i><b>其病昏惑悲忘，</b><i>从水化也。少徵与少羽同，上商与正商同，</i><b>邪伤心也。</b><i>凝惨溧冽则暴雨霖霪，</i><b>眚于九。</b><i>其主骤注雷霆震惊，沉阴淫雨。</i>",[h0.TAI_YIN_126_B]:"<i>卑监之纪，是谓减化，化气不令，生政独彰，长气整，雨乃愆，收气平，风寒并兴，草木荣美，秀而不实，成而秕也，其气散，其用静定，</i><b>其动疡溃痈肿，其发濡滞，其脏脾，</b><i>其果李栗，其实肉核，其谷豆麻，其味酸甘，其色苍黄，其畜牛犬，其虫倮毛，其主飘怒振发，其声宫角，</i><b>其病留满否塞，</b><i>从木化也。少宫与少角同，上宫与正宫同，其主谷饪不化，</i><b>其病飧泄，邪伤脾也。</b><i>振拉飘扬则苍干散落，</i><b>其眚四维。</b><i>其主败折虎狼，清气乃用，生政乃辱。</i>",[h0.YANG_MING_28_B]:"<i>从革之纪，是谓折收，收气乃后，生气乃扬，长化合德，火政乃宣，庶类以蕃，其气扬，其用躁切，</i><b>其动铿禁瞀厥，其发咳喘，其脏肺，</b><i>其果李杏，其实壳络，其谷麻麦，其味苦辛，其色白丹，其畜鸡羊，其虫介羽，其主明曜炎烁，其声商徵，</i><b>其病嚏咳鼽衄，</b><i>从火化也。少商与少徵同，上商与正商同，上角与正角同，</i><b>邪伤肺也。</b><i>炎光赫烈则冰雪霜雹，</i><b>眚于七。</b><i>其主鳞伏彘鼠，岁气早至，乃生大寒。</i>",[h0.TAI_YANG_39_B]:"<i>涸流之纪，是谓反阳，藏令不举，化气乃昌，长气宣布，蛰虫不藏，土润水泉减，草木条茂，荣秀满盛，其气滞，其用渗泄，</i><b>其动坚止，其发燥槁，其脏肾，</b><i>其果枣杏，其实濡肉，其谷黍稷，其味甘咸，其色䶖玄，其畜彘牛，其虫鳞倮，其主埃郁昏翳，其声羽宫，</i><b>其病痿厥坚下，</b><i>从土化也。少羽与少宫同，上宫与正宫同，</i><b>其病癃閟，邪伤肾也。</b><i>埃昏骤雨则振拉摧拔，</i><b>眚于一。</b><i>其主毛显狐貉，变化不藏。</i>",appendText:"故乘危而行，不速而至，暴虐无德，灾反及之，微者复微，甚者复甚，气之常也。"},taiGuo:{[h0.JUE_YIN_410_T]:"<i>发生之纪，是谓启陈，土疏泄，苍气达，阳和布化，阴气乃随，生气淳化，万物以荣，其化生，其气美，其政散，其令条舒，</i><b>其动掉眩巅疾，</b><i>其德鸣靡启坼，其变振拉摧拔，其谷麻稻，其畜鸡犬，其果李桃，其色青黄白，其味酸甘辛，其象春，</i><b>其经足厥阴少阳，其脏肝脾，</b><i>其虫毛介，其物中坚外坚，<i><b>其病怒，上微则其气逆，其病吐利</b><i>，不务其德则收气复，秋气劲切，甚则肃杀，清气大至，草木雕零，邪乃伤肝。</i>",[h0.SHAO_YIN_115_T]:"<i>赫曦之纪，是谓蕃茂，阴气内化，阳气外荣，炎暑施化，物得以昌，其化长，其气高，其政动，其令鸣显，</i><b>其动炎灼妄扰，</b><i>其德暄暑郁蒸，其变炎烈沸腾，其谷麦豆，其畜羊彘，其果杏栗，其色赤白玄，其味苦辛咸，其象夏，</i><b>其经手少阴太阳、手厥阴少阳，其脏心肺，</b><i>其虫羽鳞，其物脉濡，</i><b>其病笑疟，疮疡血流，狂妄目赤。</b><i>上羽与正徵同，其收齐，</i><b>其病痓</b><i>，上徵而收气后也。暴烈其政，藏气乃复，时见凝惨，甚则雨水霜雹切寒，邪伤心也。</i>",[h0.TAI_YIN_126_T]:"<i>敦阜之纪，是谓广化，厚德清静，顺长以盈，至阴内实，物化充成，烟埃朦郁，见于厚土，大雨时行，湿气乃用，燥政乃辟，其化圆，其气丰，其政静，其令周备，</i><b>其动濡积并稸，</b><i>其德柔润重淖，其变震惊飘骤崩溃，其谷稷麻，其畜牛犬，其果枣李，其色黅玄苍，其味甘咸酸，其象长夏，</i><b>其经足太阴阳明，其脏脾肾，</b><i>其虫倮毛，其物肌核，</i><b>其病腹满，四肢不举</b><i>，大风迅至，邪伤脾也。</i>",[h0.YANG_MING_28_T]:"<i>坚成之纪，是谓收引，天气洁，地气明，阳气随，阴治化，燥行其政，物以司成，收气繁布，化洽不终，其化成，其气削，其政肃，其令锐切，</i><b>其动暴折疡疰，</b><i>其德雾露萧飋，其变肃杀雕零，其谷稻黍，其畜鸡马，其果桃杏，其色白青丹，其味辛酸苦，其象秋，</i><b>其经手太阴阳明，其脏肺肝，</b><i>其虫介羽，其物壳络，</i><b>其病喘喝胸凭仰息。</b><i>上徵与正商同，其生齐，</i><b>其病咳。</b><i>政暴变则名木不荣，柔脆焦首，长气斯救，大火流，炎烁且至，蔓将槁，邪伤肺也。</i>",[h0.TAI_YANG_39_T]:"<i>流衍之纪，是谓封藏，寒司物化，天地严凝，藏政以布，长令不扬，其化凛，其气坚，其政谧，其令流注，</i><b>其动漂泄沃涌，</b><i>其德凝惨寒氛，其变冰雪霜雹，其谷豆稷，其畜彘牛，其果栗枣，其色黑丹黅，其味咸苦甘，其象冬，</i><b>其经足少阴太阳，其脏肾心，</b><i>其虫鳞倮，其物濡满，</i><b>其病胀，</b><i>上羽而长气不化也。政过则化气大举，而埃昏气交，大雨时降，邪伤肾也。</i>",appendText:"不恒其德，则所胜来复，政恒其理，则所胜同化，此之谓也。"}},wo={title:"天气下临脏气上从病候(《五常政大论》)",[K.SHAO_YANG]:"<i>少阳司天，火气下临，肺气上从，白起金用，草木眚；火见燔焫，革金且耗，大暑以行，</i><b>咳嚏鼽衄鼻窒，疮疡寒热胕肿。</b><i>风行于地，尘沙飞扬，</i><b>心痛胃脘痛，厥逆膈不通，其主暴速。</b>",[K.YANG_MING]:"<i>阳明司天，燥气下临，肝气上从，苍起木用而立，土乃眚；凄沧数至，木伐草萎，</i><b>胁痛目赤，掉振鼓栗，筋痿不能久立。</b><i>暴热至，土乃暑，阳气郁发，</i><b>小便变，寒热如疟，甚则心痛</b><i>，火行于槁，流水不冰，蛰虫乃见。</i>",[K.TAI_YANG]:"<i>太阳司天，寒气下临，心气上从，而火用丹起，金乃眚；寒清时举，胜则水冰。火气高明，</i><b>心热烦，嗌干善渴，鼽嚏，喜悲数欠。</b><i>热气妄行，寒乃复，霜不时降，</i><b>善忘，甚则心痛。</b><i>土乃润，水丰衍，寒客至，沉阴化，湿气变物，</i><b>水饮内稸，中满不食，皮痛肉苛，筋脉不利，甚则胕肿、身后痈。</b>",[K.JUE_YIN]:"<i>厥阴司天，风气下临，脾气上从，而土且隆，黄起，水乃眚；土用革，</i><b>体重肌肉萎，食减口爽；</b><i>风行太虚，云物摇动，</i><b>目转耳鸣。</b><i>火纵其暴，地乃暑，大热消烁，</i><b>赤沃下，</b><i>蛰虫数见，流水不冰，</i><b>其发机速。</b>",[K.SHAO_YIN]:"<i>少阴司天，热气下临，肺气上从，白起金用，草木眚；</i><b>喘呕寒热，嚏鼽衄鼻窒；</b><i>大暑流行，</i><b>甚则疮疡燔灼，</b><i>金烁石流。地乃燥清，凄沧数至，</i><b>胁痛善太息</b><i>，肃杀行，草木变。</i>",[K.TAI_YIN]:"<i>太阴司天，湿气下临，肾气上从，黑起水变，火乃眚；埃冒云雨，</i><b>胸中不利，阴痿气大衰，而不起不用；</b><i>当其时，反</i><b>腰雅痛，动转不便也，厥逆。</b><i>地乃藏阴，大寒且至，蛰虫早附，心下否痛，地裂冰坚，</i><b>少腹痛，时害于食。</b><i>乘金则止水增，味乃咸，行水减也。</i>"},Hc=[h0.JUE_YIN_410,h0.SHAO_YIN_115,h0.TAI_YIN_126,h0.YANG_MING_28,h0.TAI_YANG_39],Zc=[h0.JUE_YIN_410_T,h0.SHAO_YIN_115_T,h0.TAI_YIN_126_T,h0.YANG_MING_28_T,h0.TAI_YANG_39_T],Pc=[h0.JUE_YIN_410_B,h0.SHAO_YIN_115_B,h0.TAI_YIN_126_B,h0.YANG_MING_28_B,h0.TAI_YANG_39_B];function s2(e,t){for(let n of e){const u=xe.get(n);for(let i of u.years)if(i.ganZhi===t)return pn({liuQiKey:n},i)}}function Lc(e){const t=s2(Hc,e);if(t)return l1(pn({},t),{zhongYunType:fe.PING});const n=s2(Zc,e);if(n)return l1(pn({},n),{zhongYunType:fe.TAIGUO});const u=s2(Pc,e);if(u)return l1(pn({},u),{zhongYunType:fe.BUJI})}function o2(e,t,n,u,i){const{key:a,flagKey:s,nums:r,yunQiYear:o}=e;if(!a||!s||!i)return;const l=`${e.key}_${r}`,c=`${l}_${s[0]}`,g=s[0]==="T"?Wt.taiGuo:Wt.buJi,h=Wt.pingQi[h0[l]],f=g[h0[c]],E=wo[n==null?void 0:n.key],A=Lc(o);if(A.zhongYunType===fe.PING&&h&&t[0].array.push(l1(pn({},A),{text:h,appendText:Wt.pingQi.appendText,assistText:f,yunQiYearTypeName:"平气",type:u})),A.zhongYunType!==fe.PING&&f){const B=A.zhongYunType===fe.TAIGUO;t[0].array.push(l1(pn({},A),{text:f,assistText:h,appendText:B?Wt.taiGuo.appendText:Wt.buJi.appendText,yunQiYearTypeName:B?"太过":"不及",type:u}))}E&&t[1].array.push({key:n==null?void 0:n.key,text:E,type:u})}const $c=e=>Ci(e,"liuQiKey"),Uc=e=>Ci(e,"key");function qc(e){const{birth:t,illness:n,current:u}=e,i=[{title:Wt.title,array:[],colKey:"wczdl_sqzj"},{title:wo.title,array:[],colKey:"qijbdl_tqxl"}],a=mn(t);o2(a,i,t.siTianOption,"命",t.isShowDetail);const s=mn(n);o2(s,i,n.siTianOption,"病",n.isShowDetail);const r=mn(u);return o2(r,i,u.siTianOption,"时",u.isShowDetail),[$c(i[0]),Uc(i[1])]}var Rc=Object.defineProperty,Xc=Object.defineProperties,Jc=Object.getOwnPropertyDescriptors,a5=Object.getOwnPropertySymbols,Qc=Object.prototype.hasOwnProperty,Wc=Object.prototype.propertyIsEnumerable,s5=(e,t,n)=>t in e?Rc(e,t,{enumerable:!0,configurable:!0,writable:!0,value:n}):e